## My answer to the prompt

A controlled autocomplete can filter suggestions as the user types, hide the list when there are no matches, and mark a value invalid unless it matches an option. For very large lists, limit the number of rendered suggestions or use a virtualization library.

```tsx
import { useMemo, useState } from "react";

type InputProps = {
  options: string[];
  value: string;
  onChange: (value: string) => void;
  placeholder?: string;
  maxSuggestions?: number;
};

export function Input({
  options,
  value,
  onChange,
  placeholder,
  maxSuggestions = 50,
}: InputProps) {
  const [open, setOpen] = useState(false);

  const matches = useMemo(() => {
    const query = value.trim().toLowerCase();
    if (!query) return [];
    return options
      .filter((option) => option.toLowerCase().includes(query))
      .slice(0, maxSuggestions);
  }, [options, value, maxSuggestions]);

  const isValid =
    value.trim() === "" ||
    options.some((option) => option.toLowerCase() === value.trim().toLowerCase());

  return (
    <div>
      <input
        value={value}
        placeholder={placeholder}
        aria-invalid={!isValid}
        onFocus={() => setOpen(true)}
        onChange={(event) => {
          onChange(event.target.value);
          setOpen(true);
        }}
        style={{ border: `1px solid ${isValid ? "#999" : "red"}` }}
