  options: readonly string[]
  value: string
  onChange: (value: string) => void
  validate?: (value: string) => boolean
}

export function Input({ options, value, onChange, validate }: InputProps) {
  const [open, setOpen] = useState(false)
  const query = value.trim().toLocaleLowerCase()

  const matches = useMemo(() => {
    if (!query) return []
    return options.filter(option =>
      option.toLocaleLowerCase().includes(query)
    )
  }, [options, query])

  const isValid = validate
    ? validate(value)
    : value.trim() === '' ||
      options.some(option => option.toLocaleLowerCase() === query)

  return (
    <div>
      <input
        value={value}
        onChange={event => {
          onChange(event.target.value)
          setOpen(true)
        }}
        onKeyDown={event => {
          if (event.key === 'Escape') setOpen(false)
        }}
        aria-invalid={!isValid}
        style={{ borderColor: isValid ? undefined : 'red' }}
      />
      {open && matches.length > 0 && (
        <ul>
          {matches.slice(0, 100).map((option, index) => (
            <li key={`${option}-${index}`}>
              <button
                type="button"
                onClick={() => {
                  onChange(option)
                  setOpen(false)
                }}
              >
                {option}
              </button>
            </li>
          ))}
        </ul>
      )}
    </div>
  )
}
```

For exceptionally large lists, I would replace the rendered list with a virtualized list (for example, using `react-window`) rather than rendering every match. A production version should also support keyboard selection, dismissal on outside clicks, and accessible combobox/listbox semantics.

